package dev.itzgamesgd.moreminecrafts.fishing;
import java.util.Arrays;
import net.minecraft.util.RandomSource;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FishingLogicTest {
 @Test void higherReelsIncludeLowerSpeciesWithoutChangingWeights(){var one=FishingLogic.accessibleSpecies(1);var three=FishingLogic.accessibleSpecies(3);assertEquals(4,one.size());assertEquals(12,three.size());assertTrue(three.containsAll(one));assertEquals(FishSpecies.CRUCIAN_CARP.encounterWeight(),one.getFirst().encounterWeight());}
 @Test void insufficientMinnowDoesNotBlockEncounterButDeniesCapture(){var pool=FishingLogic.accessibleSpecies(3);assertTrue(pool.contains(FishSpecies.BLUE_MARLIN));assertFalse(FishingLogic.canCapture(FishSpecies.BLUE_MARLIN,0));assertFalse(FishingLogic.canCapture(FishSpecies.BLUE_MARLIN,2));assertTrue(FishingLogic.canCapture(FishSpecies.BLUE_MARLIN,3));}
 @Test void exactCrankbaitDistributionsAreComplete(){assertArrayEquals(new int[]{45,30,16,7,2},FishingLogic.gradeWeights(0));assertArrayEquals(new int[]{30,32,22,12,4},FishingLogic.gradeWeights(1));assertArrayEquals(new int[]{10,25,32,24,9},FishingLogic.gradeWeights(2));assertArrayEquals(new int[]{0,8,34,38,20},FishingLogic.gradeWeights(3));for(int t=0;t<=3;t++)assertEquals(100,Arrays.stream(FishingLogic.gradeWeights(t)).sum());}
 @Test void expectedWeightIsSpeciesSpecificMonotonicAndBounded(){for(FishSpecies s:FishSpecies.values()){int minL=s.lengthDistribution().minimum(),maxL=s.lengthDistribution().maximum(),minW=s.weightDistribution().minimum(),maxW=s.weightDistribution().maximum(),prev=minW;for(int l=minL;l<=maxL;l++){int e=s.expectedWeightForLength(l);assertTrue(e>=prev,s.id());assertTrue(e>=minW&&e<=maxW);prev=e;}assertEquals(minW,s.expectedWeightForLength(minL));assertEquals(maxW,s.expectedWeightForLength(maxL));}}
 @Test void sameLengthAllowsBoundedIndividualVariation(){for(FishSpecies s:FishSpecies.values()){int l=s.lengthDistribution().minimum()+(s.lengthDistribution().maximum()-s.lengthDistribution().minimum())/2;int light=s.weightForLength(l,-1),heavy=s.weightForLength(l,1);assertTrue(light>=s.weightDistribution().minimum());assertTrue(heavy<=s.weightDistribution().maximum());assertTrue(heavy>light);}}
 @Test void randomSizeRollsStayBoundedAndIgnoreGradeAndModules(){for(FishSpecies s:FishSpecies.values())for(int seed=0;seed<100;seed++){int l=FishingLogic.rollLength(s,RandomSource.create(seed)),w=FishingLogic.rollWeight(s,l,RandomSource.create(seed+1000));assertTrue(l>=s.lengthDistribution().minimum()&&l<=s.lengthDistribution().maximum());assertTrue(w>=s.weightDistribution().minimum()&&w<=s.weightDistribution().maximum());for(int g=1;g<=FishingGrade.MAX;g++)for(int tier=0;tier<=FishingEquipmentTier.MAX;tier++){assertEquals(l,FishingLogic.rollLength(s,RandomSource.create(seed)));assertEquals(w,FishingLogic.rollWeight(s,l,RandomSource.create(seed+1000)));}}}
 @Test void gradeMultipliersAndSizeValueRemainBounded(){FishSpecies s=FishSpecies.COMMON_CARP;double[] mult={0,1,1.15,1.4,1.8,2.5};for(int g=1;g<=5;g++)assertEquals(mult[g],FishValue.gradeMultiplier(g),0.0001);int minL=s.lengthDistribution().minimum(),maxL=s.lengthDistribution().maximum(),minW=s.weightDistribution().minimum(),maxW=s.weightDistribution().maximum();assertEquals(s.baseValue(),FishValue.calculate(s,1,minL,minW),0.0001);assertEquals(s.baseValue()*2.5,FishValue.calculate(s,5,minL,minW),0.0001);assertEquals(s.baseValue()*1.75,FishValue.calculate(s,1,maxL,maxW),0.0001);assertEquals(s.baseValue()*2.5*1.75,FishValue.calculate(s,5,maxL,maxW),0.0001);}
}
